import React, { useEffect, useState } from "react";
import { useParams, useNavigate, useLocation } from "react-router-dom";
import Sidebar from "../components/Sidebar";
import "../styles/Lesson.css";

// Question bank for different video topics - organized by video title keywords
const questionBank = {
  "Introduction to Biology": [
    { question: "What is the primary focus of biology?", options: ["The study of rocks", "The study of living organisms and life processes", "The study of weather patterns", "The study of stars"], correct: 1 },
    { question: "Which of the following is a key characteristic of living organisms?", options: ["Static structure", "Ability to grow and reproduce", "Inability to change", "No need for energy"], correct: 1 },
  ],
  "Scientific Method": [
    { question: "Which step comes first in the scientific method?", options: ["Hypothesis", "Observation", "Conclusion", "Data collection"], correct: 1 },
    { question: "What is a hypothesis?", options: ["A proven fact", "An educated guess based on observations", "A final answer", "A type of experiment"], correct: 1 },
    { question: "In the scientific method, what follows hypothesis formation?", options: ["Observation", "Experimentation", "Conclusion", "Theory"], correct: 1 },
  ],
  "What do Biologists Do": [
    { question: "What do biologists primarily study?", options: ["Rocks and minerals", "Living organisms and their interactions", "Chemical reactions only", "Planetary movements"], correct: 1 },
    { question: "Which profession focuses on studying ecosystems?", options: ["Chemist", "Ecologist", "Physicist", "Geologist"], correct: 1 },
  ],
  "Organized Life": [
    { question: "Which is the smallest unit of life?", options: ["Tissue", "Organism", "Cell", "Molecule"], correct: 2 },
    { question: "What is the correct order of biological organization from smallest to largest?", options: ["Organism → Cell → Organ", "Cell → Organism → Tissue", "Cell → Tissue → Organ → Organism", "Molecule → Tissue → Cell → Organism"], correct: 2 },
  ],
  "Ecology": [
    { question: "What is ecology?", options: ["The study of cells only", "The study of organisms and their environment", "The study of chemicals", "The study of fossils"], correct: 1 },
    { question: "Which term describes all the organisms of one species in an area?", options: ["Community", "Ecosystem", "Population", "Biome"], correct: 2 },
  ],
  "The Nucleus": [
    { question: "What is the nucleus?", options: ["The cell wall", "The membrane surrounding organelles", "The membrane-bound structure containing DNA", "A type of protein"], correct: 2 },
    { question: "What is the primary function of the nucleus?", options: ["Energy production", "Protein synthesis", "Storage and regulation of genetic material", "Waste removal"], correct: 2 },
  ],
  "Stoichiometry": [
    { question: "What is stoichiometry?", options: ["The study of sound", "The calculation of reactants and products in chemical reactions", "The structure of atoms", "The study of energy"], correct: 1 },
    { question: "What do stoichiometric ratios represent?", options: ["Temperature changes", "The proportions of substances in reactions", "Density measurements", "Electrical conductivity"], correct: 1 },
  ],
  "Water & Solutions": [
    { question: "What is a solution?", options: ["A solid mixture only", "A homogeneous mixture of a solute and solvent", "A type of element", "A chemical compound"], correct: 1 },
    { question: "In a solution, what is the solvent?", options: ["The substance being dissolved", "The substance doing the dissolving", "Both equally", "Neither of the above"], correct: 1 },
  ],
  "Acid-Base Reactions": [
    { question: "What is the pH range for neutral solutions?", options: ["0-7", "7", "7-14", "0-14"], correct: 1 },
    { question: "What is formed when an acid reacts with a base?", options: ["More acid", "A salt and water", "A gas", "A metal"], correct: 1 },
  ],
  "Redox Reactions": [
    { question: "What does 'redox' stand for?", options: ["Reduction-oxidation", "Reactive-oxide", "Reduced-oxidized", "Reversible-oxide"], correct: 0 },
    { question: "In a redox reaction, what is oxidation?", options: ["Loss of electrons", "Gain of electrons", "Loss of atoms", "Gain of atoms"], correct: 0 },
  ],
  "The Ideal Gas Law": [
    { question: "What is the ideal gas law equation?", options: ["PV=nRT", "E=mc²", "F=ma", "V=IR"], correct: 0 },
    { question: "In the ideal gas law, what does R represent?", options: ["Radius", "Resistance", "The gas constant", "Reactivity"], correct: 2 },
  ],
  "Enthalpy": [
    { question: "What is enthalpy?", options: ["A type of acid", "The heat energy of a system at constant pressure", "The speed of a reaction", "A type of metal"], correct: 1 },
    { question: "What indicates an exothermic reaction?", options: ["Positive enthalpy change", "Negative enthalpy change", "No enthalpy change", "Constant enthalpy"], correct: 1 },
  ],
  "Types of Chemical Bonds": [
    { question: "What type of bond forms when electrons are shared?", options: ["Ionic bond", "Covalent bond", "Metallic bond", "Hydrogen bond"], correct: 1 },
    { question: "What type of bond forms between a metal and nonmetal?", options: ["Covalent", "Ionic", "Hydrogen", "Metallic"], correct: 1 },
  ],
  "Periodic Table": [
    { question: "What does the periodic table organize elements by?", options: ["Size only", "Color", "Atomic number and chemical properties", "Density only"], correct: 2 },
    { question: "Which element has atomic number 1?", options: ["Helium", "Hydrogen", "Carbon", "Nitrogen"], correct: 1 },
  ],
};

// Function to generate worksheets based on video titles
function generateWorksheets(videos) {
  if (!videos || videos.length === 0) {
    return { worksheet1: [], worksheet2: [] };
  }

  let allQuestions = [];

  // Collect questions from video titles
  videos.forEach(video => {
    const videoTitle = video.title || "";
    // Check if title matches a key in questionBank
    Object.keys(questionBank).forEach(key => {
      if (videoTitle.toLowerCase().includes(key.toLowerCase())) {
        allQuestions.push(...questionBank[key]);
      }
    });
  });

  // If no questions found, create generic questions about the lesson
  if (allQuestions.length === 0) {
    allQuestions = videos.map((video, idx) => ({
      question: `What is the main topic of the "${video.title}" video?`,
      options: [video.title, "A different topic", "Not related to the course", "A historical event"],
      correct: 0,
    }));
  }

  // Shuffle and split into two worksheets
  const shuffled = allQuestions.sort(() => Math.random() - 0.5);
  const worksheet1 = shuffled.slice(0, 5).map((q, idx) => ({ ...q, id: idx + 1 }));
  const worksheet2 = shuffled.slice(5, 10).map((q, idx) => ({ ...q, id: idx + 1 }));

  return { worksheet1, worksheet2 };
}

export default function Lesson() {
  const { lessonId } = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const { lesson } = location.state || {};

  const [tutors, setTutors] = useState([]);
  const [sessions, setSessions] = useState([]);
  const [selectedTutor, setSelectedTutor] = useState(null);
  const [signupProcessing, setSignupProcessing] = useState(false);
  const [bookingStatus, setBookingStatus] = useState(null);
  const [bookedSession, setBookedSession] = useState(null);
  const [watchedVideos, setWatchedVideos] = useState({});
  const [currentVideoPlayer, setCurrentVideoPlayer] = useState(null);
  const [activeStep, setActiveStep] = useState(1);
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState(null);
  const [worksheet1Answers, setWorksheet1Answers] = useState({});
  const [worksheet2Answers, setWorksheet2Answers] = useState({});
  const [worksheet1Submitted, setWorksheet1Submitted] = useState(false);
  const [worksheet2Submitted, setWorksheet2Submitted] = useState(false);
  const [step3Completed, setStep3Completed] = useState(false);
  const [newQuestion, setNewQuestion] = useState("");
  const [newAnswer, setNewAnswer] = useState("");
  const [communityPosts, setCommunityPosts] = useState([
    {
      id: 1,
      author: "Alex Chen",
      type: "question",
      content: "Can someone explain the difference between mitosis and meiosis? I'm confused about when each process happens.",
      timestamp: "2 hours ago",
      replies: 5,
      likes: 12,
    },
    {
      id: 2,
      author: "Jordan Smith",
      type: "answer",
