                                >
                                  {signupProcessing && bookedSession?.id === session.id ? "Booking..." : (bookedSession && bookedSession.id === session.id) ? "Booked ✓" : session.spots_left === 0 ? "Full" : "Book"}
                                </button>
                              </div>
